import { readFileSync, writeFileSync } from "node:fs";
import { sha256, stableJson } from "/tmp/v53/claude-plugin/skills/korean-prose-editor/scripts/lib.mjs";

const D = "/tmp/claude-0/-tmp-nlm-r06-p5a-prose-1/8f5bc1e3-aeff-4c48-995f-171df75007fd/scratchpad/kpe";
const source = readFileSync(`${D}/source.txt`, "utf8");
const draft = JSON.parse(readFileSync(`${D}/editing-draft.json`, "utf8"));
const selection = JSON.parse(readFileSync(`${D}/selection.json`, "utf8"));
const units = JSON.parse(readFileSync(`${D}/units.json`, "utf8"));

const srcDigest = sha256(source);
if (srcDigest !== draft.sourceDigest || srcDigest !== selection.sourceDigest) throw new Error(`source digest mismatch ${srcDigest}`);

const sorted = [...draft.edits].sort((a, b) => a.start - b.start);
let prevEnd = -1;
for (const e of sorted) {
  const unit = units.units.find((u) => u.unitId === e.unitId);
  const dec = selection.decisions.find((d) => d.unitId === e.unitId);
  if (!unit || dec?.action !== "edit") throw new Error(`unit not editable ${e.id}`);
  if (!(e.start >= unit.start && e.end <= unit.end && e.start <= e.end)) throw new Error(`range outside unit ${e.id}`);
  if (e.start < prevEnd) throw new Error(`overlap ${e.id}`);
  if (!dec.issueRanges.some((r) => e.start < r.end && r.start < e.end)) throw new Error(`no issue overlap ${e.id}`);
  if (e.sourceDigest !== srcDigest || e.actorId !== draft.actorId) throw new Error(`bad edit meta ${e.id}`);
  const orig = source.slice(e.start, e.end);
  if (orig.length && e.replacement.length && (orig[0] === e.replacement[0] || orig.at(-1) === e.replacement.at(-1))) throw new Error(`not minimal ${e.id}`);
  console.log(`${e.id} [${e.start},${e.end}) ${JSON.stringify(orig)} -> ${JSON.stringify(e.replacement)}`);
  prevEnd = e.end;
}

let candidate = source;
for (const e of [...sorted].reverse()) candidate = candidate.slice(0, e.start) + e.replacement + candidate.slice(e.end);

const wp = {
  schemaVersion: "1.0.0",
  actorId: draft.actorId,
  sourceDigest: srcDigest,
  glossaryBinding: { schemaVersion: "1.0.0", mode: "none" },
  selectionDigest: sha256(stableJson(selection)),
  edits: draft.edits,
  candidateDigest: sha256(candidate),
};
writeFileSync(`${D}/editing.json`, JSON.stringify(wp, null, 2) + "\n");
console.log("candidate:", candidate);
console.log(JSON.stringify(wp, null, 2));

